import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;

public class CommentsConfigurationTest {

    @Test
    public void constructorCreatesEmptyCommentsMap() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        assertNotNull(configuration.getComments());
        assertEquals(0, configuration.getComments().size());
    }

    @Test
    public void constructorWithExistingCommentsCreatesCommentMap() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("path1", Arrays.asList("line1"));
        CommentsConfiguration configuration = new CommentsConfiguration(comments);
        assertNotNull(configuration.getComments());
        assertEquals(1, configuration.getComments().size());
    }

    @Test
    public void setCommentAddsNewEntry() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        configuration.setComment("path1", "line1");
        assertNotNull(configuration.getComments());
        assertEquals(1, configuration.getComments().size());
        assertTrue(configuration.getComments().containsKey("path1"));
    }

    @Test
    public void setCommentOverwritesExistingEntry() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        configuration.setComment("path1", "line1");
        configuration.setComment("path1", "newLine");
        assertNotNull(configuration.getComments());
        assertEquals(1, configuration.getComments().size());
        assertTrue(configuration.getComments().containsKey("path1"));
    }

    @Test
    public void setCommentAllowsEmptyLine() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        String[] lines = {"line1", "", "line3"};
        configuration.setComment("path1", lines);
        assertNotNull(configuration.getComments());
        assertEquals(2, configuration.getComments().size());
        assertTrue(configuration.getComments().containsKey("path1"));
    }

    @Test
    public void getAllCommentsReturnsUnmodifiableMap() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        Map<String, List<String>> comments = configuration.getAllComments();
        assertTrue(comments instanceof java.util.Map);
        assertTrue(((java.util.Map)comments).instanceof(java.util.UnmodifiableMap));
    }

    @Test
    public void getAllCommentsReturnsCorrectPathEntry() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        Map<String, List<String>> comments = configuration.getAllComments();
        assertEquals(1, comments.size());
        assertTrue(comments.containsKey("path1"));
        assertTrue(((List)comments.get("path1")).size() == 2);
    }

    @Test
    public void setCommentMultiplePaths() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        String[] lines1 = {"line11"};
        String[] lines2 = {"line21"};
        configuration.setComment("path1", lines1);
        configuration.setComment("path2", lines2);
        assertNotNull(configuration.getComments());
        assertEquals(2, configuration.getComments().size());
    }
}
